SELECT data_rows.id, data_rows.should_delete, data_rows.archived, data_rows.conversation_id, data_rows.turn_id, data_rows.sequence, data_rows.created_at, data_rows.updated_at, data_rows.created_by_user_id, data_rows.mode, data_rows.role, data_rows.status, data_rows.type, data_rows.content, data_rows.raw_content, data_rows.summary, data_rows.context_summary, data_rows.embedding_index, data_rows.tags, data_rows.interim, data_rows.elicitation_id, data_rows.parent_message_id, data_rows.superseded_by, data_rows.linked_conversation_id, data_rows.tool_name, data_rows.preamble, data_rows.iteration, data_rows.phase, data_rows.attachment_payload_id, data_rows.elicitation_payload_id FROM  (SELECT 0 AS should_delete, `id`, `archived`, `conversation_id`, `turn_id`, `sequence`, `created_at`, `updated_at`, `created_by_user_id`, `mode`, `role`, `status`, `type`, `content`, `raw_content`, `summary`, `context_summary`, `embedding_index`, `tags`, `interim`, `elicitation_id`, `parent_message_id`, `superseded_by`, `linked_conversation_id`, `tool_name`, `preamble`, `iteration`, `phase`, `attachment_payload_id`, `elicitation_payload_id` FROM message)  data_rows